// Explicit review is bound to a content snapshot; issued quotes remain immutable.
const reviewOriginalClean=cleanCalculation;
cleanCalculation=function(s){const c=reviewOriginalClean(s);for(const k of ['royalty','requiredServices','typicalProduct','approval'])if(s[k]!==undefined)c[k]=structuredClone(s[k]);c.lines.forEach((l,i)=>{l.costCategory=s.lines[i].costCategory||'';l.pricingMode=s.lines[i].pricingMode||'cost';l.normNote=s.lines[i].normNote||'';for(const k of ['basePrice','baseUnit','sourceFormula','sourceParameters','sourceFinalCost','physicalQuantity','physicalUnit','productivity','productivityUnit','productivityStatus','unitChangeNotice','workshop','productionOrder'])if(s.lines[i][k]!==undefined)l[k]=structuredClone(s.lines[i][k]);});if(s.archive&&s.archive.signature===CalculationArchive.signature(s)){c.archive=structuredClone(s.archive);c.archive.signature=CalculationArchive.signature(c)}return c;};
const reviewValid=validState;
validState=function(s){return reviewValid(s)&&(s.royalty===undefined||(Number.isFinite(s.royalty)&&s.royalty>=0))&&s.lines.every(l=>(l.pricingMode===undefined||['calculated','individual','cost','client'].includes(l.pricingMode))&&(!l.pricingMode||!['client'].includes(l.pricingMode)||l.kind==='work'));};
const reviewPersist=persist;
persist=function(){if(state.approval&&!ReviewCore.approved(state))delete state.approval;reviewPersist();if(!window.draftSaveFailed)$('saveState').textContent='Черновик сохранён в этом браузере';if(typeof cloudReady!=='undefined'&&cloudReady){cloudDirty++;scheduleCloud();}};
function reviewSetting(k,v){state[k]=v;persist();render();}
function serviceSetting(k,v){state.requiredServices={...(state.requiredServices||{installation:/монтаж|Комплексный/.test(state.scope),delivery:/Комплексный/.test(state.scope),design:/Проектирование|Комплексный/.test(state.scope)}),[k]:v};const r=state.requiredServices;state.scope=r.delivery?'Комплексный заказ':r.installation?'Изготовление и монтаж':r.design?'Проектирование и изготовление':state.type==='Сервисные работы'?'Сервис':'Изготовление';persist();render();}
function reviewApprove(){const r=CostEngine.calculate(state);if(r.approvalIssues.length){modal('Согласование заблокировано',`<p>Исправьте пропуски и подтвердите строки. Предварительное КП доступно.</p>${r.approvalIssues.map(e=>`<div class="issue">${esc(e)}</div>`).join('')}<button onclick="$('modal').close();go(4)">К проверке расчёта</button>`);return;}state.approval={date:stamp(),signature:ReviewCore.signature(state)};persist();render();toast('Текущая версия согласована');}
function reviewPanel(){const r=CostEngine.calculate(state),ok=!r.preliminary;return `<div class="card review-panel"><div class="cardhead"><h2>${ok?'Согласовано':'Требуется проверка'}</h2><button class="primary" onclick="reviewApprove()">Согласовать текущую версию</button></div><p>${ok?'Согласование относится к этому составу, тиражу, нормам и ценам. Изменение снимает согласование.':`Замечаний перед согласованием: ${r.approvalIssues.length}. До согласования КП помечается предварительным.`}</p>${r.scopeIssues.map(e=>`<div class="issue">${esc(e)} <button onclick="go(0)">Состав заказа</button></div>`).join('')}${r.profitIncomplete?'<p class="warning">Есть готовые цены заказчику: их внутренние затраты не заданы. Показанная наценка не является полной прибылью заказа.</p>':''}<div class="metricline"><span>Производственная себестоимость без роялти</span><b>${money(r.productionCost)}</b></div><div class="metricline"><span>Роялти ${dec(state.royalty||0)}%</span><b>${money(r.royalty)}</b></div><div class="metricline"><span>Готовые цены заказчику (уже с НДС)</span><b>${money(r.fixedGross)}</b></div></div>`;}
function priceReviewHTML(r){const complete=!r.partial&&!r.profitIncomplete,show=v=>complete&&Number.isFinite(v)?money(v):'—',rows=[['Себестоимость материалов · НДС учтён в исходных данных',r.M/r.q,r.M],['Изготовление · НДС учтён в исходных данных',r.manufacturingUnit,r.manufacturing],['Себестоимость с НДС',r.costUnit,r.C],['Стоимость с прибылью',r.unit,r.total],['Прибыль до вычета налогов',r.profitBeforeTax===null?null:r.profitBeforeTax/r.q,r.profitBeforeTax],['Прибыль после налога на прибыль',r.profitAfterTax===null?null:r.profitAfterTax/r.q,r.profitAfterTax]];return `<div class="card price-review-breakdown"><div class="cardhead"><h2>Проверка цены</h2><span class="small">НДС материалов уже учтён в исходных ценах · налог на прибыль ${dec(r.profitTax)}%</span></div><div class="tablewrap"><table><thead><tr><th>Показатель</th><th class="number">На изделие</th><th class="number">На партию · ${dec(r.q)} шт.</th></tr></thead><tbody>${rows.map(([label,unit,batch])=>`<tr><td>${label}</td><td class="number">${show(unit)}</td><td class="number">${show(batch)}</td></tr>`).join('')}</tbody></table></div><p class="small">При неполном расчёте прибыль и итоговые показатели остаются неизвестными. Стоимость с прибылью показана с НДС продажи.</p></div>`;}
const reviewRender=render;
render=function(){reviewRender();if(page===0){const services=state.requiredServices||{installation:/монтаж|Комплексный/.test(state.scope),delivery:/Комплексный/.test(state.scope),design:/Проектирование|Комплексный/.test(state.scope)};const card=document.createElement('div');card.className='card';card.innerHTML=`<h2>Обязательный состав заказа</h2><p class="small">Каждый выбранный раздел должен иметь работу в расчёте. Несоответствие блокирует согласование.</p>${[['design','Проектирование'],['installation','Монтаж'],['delivery','Доставка заказчику']].map(([k,n])=>`<label class="checkrow"><input type="checkbox" ${services[k]?'checked':''} onchange="serviceSetting('${k}',this.checked)">${n}</label>`).join('')}<label class="checkrow"><input type="checkbox" ${state.typicalProduct?'checked':''} onchange="reviewSetting('typicalProduct',this.checked)">Типовое изделие — разработку заново не считаем</label>`;const scope=$('f-scope');if(scope?.closest){scope.closest('.field').hidden=true;const host=document.querySelector('.calculation-form > div.card');if(host)host.append(card);else $('app').append(card);}else $('app').append(card);}
if(page===3){const card=document.createElement('div');card.className='card';card.innerHTML=`<h2>Роялти типового изделия</h2><label for="reviewRoyalty">Роялти, % от производственной себестоимости</label><input id="reviewRoyalty" type="number" min="0" step="any" value="${state.royalty??0}" onchange="reviewSetting('royalty',this.value===''?null:Number(this.value))"><p class="small">Материалы + производственные работы + их накладные + закупочный транспорт. Монтаж, доставка заказчику и само роялти исключены. Затем применяются действующие наценка и НДС.</p>`;$('app').append(card);}
if(page===1)renderPurchaseReview();if(page===2){const card=document.createElement('div');card.className='note info';card.innerHTML='Ставка и объём работы — разные входы. Для часовой ставки задайте часы; неизвестная трудоёмкость не равна нулю. Проектирование тиража задавайте на всю партию.';$('app').prepend(card);}
if($('saveState')&&!window.draftSaveFailed)$('saveState').textContent='Черновик в этом браузере · '+(typeof cloudStatus!=='undefined'?cloudStatus:'проверка сервера');};
var materialGroupState=readJSON('izdelie-material-groups-v1',{});
if(!materialGroupState||typeof materialGroupState!=='object'||Array.isArray(materialGroupState))materialGroupState={};
function materialGroupRemember(element){const key=element.dataset.materialGroup;if(!MaterialGroupingCore.sections.some(s=>s.id===key)&&!MaterialGroupingCore.types.some(t=>t.id===key))return;if(materialGroupState[key]===element.open)return;materialGroupState={...materialGroupState,[key]:element.open};try{localStorage.setItem('izdelie-material-groups-v1',JSON.stringify(materialGroupState))}catch{/* View preferences must not interrupt the calculation. */}}
function materialGroupingField(line){const automatic=MaterialGroupingCore.resolve({...line,materialType:''},CATALOG);return '<div class="field"><label for="l-materialType">Тип материала</label><select id="l-materialType"><option value="" '+(!line.materialType?'selected':'')+'>Определять автоматически</option>'+MaterialGroupingCore.sections.map(s=>'<optgroup label="'+esc(s.label)+'">'+MaterialGroupingCore.types.filter(t=>t.sectionId===s.id).map(t=>'<option value="'+t.id+'" '+(line.materialType===t.id?'selected':'')+'>'+esc(t.label)+'</option>').join('')+'</optgroup>').join('')+'</select><div class="hint">Автоматически: '+esc(automatic.sectionLabel+' / '+automatic.label)+'</div></div>'}
function materialPurchaseRows(rows){return rows.map(l=>`<tr><td data-label="Материал">${esc(l.name)}<span class="source">${l.allocation==='share'?'Только потребность':'Полная закупка на заказ'}</span>${l.group&&l.group!=='Общее изделие'?'<span class="source">'+esc(l.group)+' · '+(l.scope==='unit'?'На изделие':'На партию')+'</span>':''}</td><td data-label="Нужно">${inlineVolumeHTML(l)}</td><td data-label="Покупаем">${dec(l.purchase)} ${esc(MaterialCore.unitLabel(l.unit))}</td><td data-label="Остаток">${l.purchase===null||l.need===null?'—':dec(l.purchase-l.need)} ${esc(MaterialCore.unitLabel(l.unit))}</td><td data-label="Платим поставщику">${l.purchase===null||l.price===null?'—':money(l.purchase*l.price)}</td><td data-label="В себестоимости">${money(l.amount)}</td><td class="material-action">${materialActionsHTML(l.id)}</td></tr>`).join('');}
function materialPurchaseTable(rows,label){return '<div class="tablewrap material-table"><table aria-label="'+esc(label)+'"><thead><tr><th>Материал</th><th>Нужно</th><th>Покупаем</th><th>Остаток</th><th>Платим поставщику</th><th>В себестоимости</th><th></th></tr></thead><tbody>'+materialPurchaseRows(rows)+'</tbody></table></div>'}
function materialGroupSummary(group){const cost=group.unknownCount?(group.unknownCount===group.count?'Себестоимость неизвестна':'Известно '+money(group.knownCost))+' · без суммы: '+group.unknownCount:money(group.knownCost);return '<span class="material-group-heading"><strong>'+esc(group.label)+'</strong><span class="material-group-total">'+group.count+' поз. · '+esc(cost)+'</span></span>'}
function materialGroupDetails(group,content,sub=false){return '<details class="material-group'+(sub?' material-subgroup':'')+'" data-material-group="'+group.id+'" '+(materialGroupState[group.id]===false?'':'open')+' ontoggle="materialGroupRemember(this)"><summary>'+materialGroupSummary(group)+'</summary><div class="material-group-content">'+content+'</div></details>'}
function renderPurchaseReview(){const r=CostEngine.calculate(state),rows=r.rows.filter(l=>l.kind==='material');if(!rows.length)return;const card=document.createElement('div');card.className='card';const groups=MaterialGroupingCore.group(rows,CATALOG);card.innerHTML='<p class="small">Потребность включает запас. Остаток = закупка − потребность. Сумма в себестоимости зависит от отнесения закупки. Для листов это оценка по площади без проверки раскладки.</p><div class="material-groups">'+groups.map(g=>materialGroupDetails(g,g.types.length===1?materialPurchaseTable(g.types[0].rows,g.label):g.types.map(t=>materialGroupDetails(t,materialPurchaseTable(t.rows,g.label+' / '+t.label),true)).join(''))).join('')+'</div>';const tables=$('app').querySelectorAll('.tablewrap');if(tables.length)tables[0].outerHTML=card.innerHTML;else $('app').append(card);}

const reviewResult=renderResult;
renderResult=function(){reviewResult();if(mode==='internal'){const r=CostEngine.calculate(state);$('app').insertAdjacentHTML('afterbegin',reviewPanel()+priceReviewHTML(r));if(r.profitIncomplete){for(const el of $('app').querySelectorAll('.kpi .small'))if(el.textContent==='Прибыль / шт. до НДС')el.textContent='Расчётная наценка / шт. (затраты услуг неполные)';}}};
const reviewEdit=editLine;
editLine=function(id){reviewEdit(id);const oldCategory=$('l-category');if(oldCategory?.closest)oldCategory.closest('.field').remove();const l=editableLine(id);if(!l||!$('lineForm'))return;if(l.kind==='material')$('lineForm').insertAdjacentHTML('afterbegin',materialGroupingField(l));if(l.kind==='work'){$('lineForm').insertAdjacentHTML('afterbegin',`<div class="field"><label for="reviewCategory">Назначение работы</label><select id="reviewCategory">${[['production','Изготовление'],['design','Проектирование'],['installation','Монтаж'],['delivery','Доставка заказчику']].map(([k,n])=>`<option value="${k}" ${ReviewCore.category(l)===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="reviewPricing">Способ задания цены</label><select id="reviewPricing"><option value="cost">Затрата компании — начислить накладные, наценку и НДС</option><option value="client" ${l.pricingMode==='client'?'selected':''}>Готовая цена заказчику с НДС — без начислений сверху</option></select></div><p class="small">Для готовой цены на партию выберите «Ко всей партии» и объём 1. Её внутренние затраты неизвестны и не включаются в прибыль.</p><div class="field"><label for="reviewNorm">Основание нормы / что включено в ставку</label><input id="reviewNorm" value="${esc(l.normNote||'')}" placeholder="Часы, число слоёв, включённые расходники…"></div>`);}}
const reviewCommit=commitLine;
commitLine=function(e,id){const l=editableLine(id);const extra=$('reviewPricing')?{pricingMode:$('reviewPricing').value,costCategory:$('reviewCategory').value,normNote:$('reviewNorm').value}:null;reviewCommit(e,id);if(!$('modal').open&&extra){Object.assign(l,extra);persist();render();}};
const reviewClient=clientDocument;
clientDocument=function(r){let html=reviewClient(r);const rows=reviewPublicRows(state,r);const body=rows.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.qty} шт.</td><td class="number">${money(l.unit)}</td><td class="number">${money(l.total)}</td></tr>`).join('');html=html.replace(/<tbody>[\s\S]*?<\/tbody>/,'<tbody>'+body+'</tbody>');if(!r.preliminary)html=html.replace('Предварительный расчёт','Согласованный расчёт').replace('Цена предварительная и требует согласования комплектности, объёмов, норм и актуальности цен.','Цена согласована для указанной версии.');return html;};
function reviewPublicRows(c,r){const factor=1+c.vat/100, rows=[];let services=0;for(const cat of ['design','installation','delivery']){const lines=r.rows.filter(l=>l.kind==='work'&&ReviewCore.category(l)===cat);if(!lines.length)continue;const gross=lines.reduce((sum,l)=>{if(l.pricingMode==='client')return sum+(l.amount||0);const amount=l.amount||0,over=amount*c.overhead/100;const markup=c.markupBase==='cost'||!c.markupBase?(amount+over)*c.markup/100:amount*c.markup/100;return sum+(amount+over+markup)*factor;},0);const total=BusinessCore.round(gross);services+=total;rows.push({name:{design:'Проектирование',installation:'Монтаж',delivery:'Доставка заказчику'}[cat],qty:1,unit:total,total});}const total=BusinessCore.round(r.total-services);return [{name:c.name,qty:c.qty,unit:total/c.qty,total},...rows];}
const reviewPublic=BusinessCore.publicDocument;
BusinessCore.publicDocument=function(draft,company,calculate){const d=reviewPublic(draft,company,calculate),items=[];draft.items.forEach((item,i)=>{const r=calculate(item.calculation,item.qty),parts=reviewPublicRows({...item.calculation,qty:item.qty},r),target=d.items[i].total,ratio=r.total?target/r.total:1;let rest=target;for(let j=parts.length-1;j>=1;j--){parts[j].total=BusinessCore.round(parts[j].total*ratio);parts[j].unit=parts[j].total;rest=BusinessCore.round(rest-parts[j].total);}parts[0].total=rest;parts[0].unit=rest/parts[0].qty;for(const row of parts)items.push({...d.items[i],...row,position:items.length+1,tax:BusinessCore.round(row.total-row.total/(1+d.items[i].vat/100))});});d.items=items;d.total=BusinessCore.round(items.reduce((t,l)=>t+l.total,0));d.tax=BusinessCore.round(items.reduce((t,l)=>t+l.tax,0));return d;};
const WORKING_KEY='izdelie-working-drafts-v1';
let reviewDevice=readJSON('izdelie-device-id',null);if(!reviewDevice){reviewDevice=uid();localStorage.setItem('izdelie-device-id',JSON.stringify(reviewDevice));}
function saveWorkingDraft(){const all=readJSON(WORKING_KEY,{});all[reviewDevice]={updatedAt:stamp(),calculation:structuredClone(state),quote:structuredClone(quoteDraft)};writeJSON(WORKING_KEY,all);}
const reviewPersistDraft=persist;
persist=function(){reviewPersistDraft();saveWorkingDraft();};
const reviewSaveQuote=saveDraft;
saveDraft=function(){reviewSaveQuote();saveWorkingDraft();};
function openWorkingDraft(id){const item=readJSON(WORKING_KEY,{})[id];if(!item||!validState(item.calculation)){toast('Черновик недоступен');return;}if(!keepCurrent())return;localStorage.setItem('izdelie-quote-draft-recovery',JSON.stringify(quoteDraft));state=cleanCalculation(item.calculation);if(item.quote&&Array.isArray(item.quote.items))quoteDraft=structuredClone(item.quote);persist();reviewSaveQuote();go(0);toast('Черновик открыт. Предыдущая калькуляция и КП сохранены для восстановления');}
function workingDraftPanel(){const all=readJSON(WORKING_KEY,{});return `<div class="card"><h2>Рабочие черновики с других компьютеров</h2><p class="small">Каждое устройство сохраняет собственный черновик. Синхронизируйте базу, затем выберите нужный. Открытие сохраняет предыдущую калькуляцию и КП в восстановительную копию.</p>${Object.entries(all).filter(([id])=>id!==reviewDevice).map(([id,x])=>`<div class="version-row"><div><b>${esc(x.calculation?.name)}</b><span class="source">${esc(x.updatedAt)} · ${x.calculation?.qty} шт.</span></div><button onclick="openWorkingDraft('${esc(id)}')">Продолжить этот черновик</button></div>`).join('')||'<p>Черновиков с других устройств пока нет.</p>'}<button onclick="recoverWorkingQuote()">Восстановить предыдущий черновик КП</button></div>`;}
function recoverWorkingQuote(){const q=readJSON('izdelie-quote-draft-recovery',null);if(!q||!Array.isArray(q.items)){toast('Копии КП нет');return;}quoteDraft=q;saveDraft();go(8);}
function effectiveScope(c){const s=c.requiredServices;if(!s)return c.scope;return [c.type==='Сервисные работы'?'Сервис':'Изготовление',...(s.design&&!c.typicalProduct?['проектирование']:[]),...(s.installation?['монтаж']:[]),...(s.delivery?['доставка']:[])].join(', ');}
const reviewClientScope=clientDocument;
clientDocument=function(r){return reviewClientScope(r).replace('<b>'+esc(state.scope)+'</b>','<b>'+esc(effectiveScope(state))+'</b>');};
const reviewCloud=renderCloud;
renderCloud=function(){reviewCloud();$('app').insertAdjacentHTML('beforeend',workingDraftPanel());};
function monthlyPricePanel(){const month=today().slice(0,7),review=readJSON('izdelie-price-review-v1',{});if(review.month===month)return '';return `<details class="card price-review"><summary>Ежемесячная проверка цен · ${esc(month)}<span>Требуется сверка</span></summary><p>Согласуйте перечень позиций для актуализации. Сохранённые версии и КП не обновляются автоматически.</p><label for="priceReviewScope">Согласованный перечень / основание проверки</label><textarea id="priceReviewScope" placeholder="Например: металл и покрытия для текущих заказов"></textarea><button onclick="finishPriceReview()">Зафиксировать выполненную проверку</button></details>`;}
function finishPriceReview(){const note=$('priceReviewScope')?.value.trim();if(!note){toast('Укажите согласованный перечень проверенных цен');return;}writeJSON('izdelie-price-review-v1',{month:today().slice(0,7),date:stamp(),note});render();}
const reviewRenderMonthly=render;
render=function(){reviewRenderMonthly();if([6,11,16].includes(page))$('app').insertAdjacentHTML('afterbegin',monthlyPricePanel());if(page===14)$('app').insertAdjacentHTML('beforeend',offcutPanel());};
function offcutPanel(){const entries=Object.values(readJSON('izdelie-offcuts-v1',{}));return `<div class="card"><div class="cardhead"><h2>Ведомость обрезков и остатков</h2><button onclick="addOffcutDialog()">Добавить остаток</button></div><p class="small">Фактические остатки после раскроя. Размеры вводятся вручную; площадь закупки не подтверждает пригодность обрезка. Резервирование и списание не выполняются.</p><div class="tablewrap"><table><thead><tr><th>Материал</th><th>Количество</th><th>Размеры / состояние</th><th>Заказ</th></tr></thead><tbody>${entries.map(x=>`<tr><td>${esc(x.name)}</td><td>${dec(x.qty)} ${esc(MaterialCore.unitLabel(x.unit))}</td><td>${esc(x.dimensions)}</td><td>${esc(x.order)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function addOffcutDialog(){modal('Добавить фактический остаток',`<form onsubmit="saveOffcut(event)"><div class="field"><label for="offName">Материал / марка / сечение</label><input id="offName" required></div><div class="grid2"><div class="field"><label for="offQty">Количество</label><input id="offQty" type="number" min="0.000001" step="any" required></div><div class="field"><label for="offUnit">Единица</label><input id="offUnit" value="шт." required></div></div><div class="field"><label for="offDimensions">Размеры в мм и состояние</label><input id="offDimensions" required placeholder="Например: 28×90×290 мм, годный"></div><p class="small">Заказ: ${esc(state.code||state.name)}. Пригодность и фактические размеры подтверждаются после раскроя.</p><button class="primary">Сохранить остаток</button></form>`);}
function saveOffcut(e){e.preventDefault();const qty=Number($('offQty').value);if(!Number.isFinite(qty)||qty<=0)return;const all=readJSON('izdelie-offcuts-v1',{});all[uid()]={name:$('offName').value.trim(),qty,unit:$('offUnit').value.trim(),dimensions:$('offDimensions').value.trim(),order:state.code||state.name,date:stamp()};if(writeJSON('izdelie-offcuts-v1',all)){$('modal').close();render();}}
const reviewQuoteStatus=BusinessCore.quoteTotals;
BusinessCore.quoteTotals=function(draft,calculate){const r=reviewQuoteStatus(draft,calculate);if((draft.discount||draft.items.some(i=>i.override!==null)))r.preliminary=true;return r;};
render();
